functions.required_screen_rows:
int required_screen_rows(int line_length, int screen_width)
{
    if (line_length == 0)
    {
        return 1;
    }
    else
    {
        return (line_length / screen_width) + ((line_length % screen_width) > 0);
    }
}

functions.move_cursor_in_view:
void move_cursor_in_view(TextBuffer *buffer, struct VirtualScreen *screen)
{
    Cursor buffer_cursor = {buffer->cursorRow, buffer->cursorCol};
    int cumul_req_rows = 0;
    int cur_line_required_rows;
    int cur_line = screen->render_start_line;
    if (buffer_cursor.x < screen->render_start_line)
    {
        screen->render_start_line = buffer_cursor.x;
    }
    else
    {
        while (cur_line <= buffer->last_line_loc)
        {
            cur_line_required_rows = required_screen_rows(buffer->lines[cur_line]->str_len, screen->width);
            if ((cur_line_required_rows + cumul_req_rows) > screen->height - 1)
            {
                cur_line--;
                break;
            }
            cumul_req_rows += cur_line_required_rows;
            cur_line++;
        }
        if (buffer_cursor.x > cur_line)
        {
            int rows_required = 0;
            while (cur_line <= buffer_cursor.x)
            {
                rows_required += required_screen_rows(buffer->lines[cur_line]->str_len, screen->width);
                cur_line++;
            }
            while (rows_required > 0)
            {
                rows_required -= required_screen_rows(buffer->lines[screen->render_start_line]->str_len, screen->width);
                screen->render_start_line++;
            }
        }
    }
}

functions.draw_editor_window:
void draw_editor_window(TextBuffer *buffer, struct VirtualScreen *screen)
{
    char *line = ((void *)0);
    int cur_line = screen->render_start_line;
    int lines_written = 0;
    int screen_cols;
    while (cur_line <= buffer->last_line_loc && lines_written < screen->height - 1)
    {
        screen_cols = screen->width;
        line = TextBufferGetLine(buffer, cur_line);
        if (line == ((void *)0))
        {
            panic("draw editor cant get text of current line in buffer");
        }
        if (strlen(line) > screen_cols)
        {
            int i = 0;
            int len_to_write;
            do
            {
                len_to_write = screen_cols < strlen(&line[i]) ? screen_cols : strlen(&line[i]);
                screen_append(&line[i], len_to_write);
                screen_append("\r\n", 2);
                screen_append("\x1b[K", 3);
                i += len_to_write;
                lines_written++;
                if (lines_written == screen->height - 2)
                {
                    break;
                }
            } while (i < strlen(line) - 1);
        }
        else
        {
            screen_append(line, strlen(line));
            screen_append("\r\n", 2);
            lines_written++;
        }
        free(line);
        cur_line++;
    }
    for (; lines_written < screen->height - 2; lines_written++)
    {
        screen_append("\r\n", 2);
    }
}

functions.set_virtual_cursor_position:
void set_virtual_cursor_position(TextBuffer *buffer, struct VirtualScreen *screen)
{
    int current_line = screen->render_start_line;
    int virtual_cursor_row = 1;
    int required_rows;
    while (current_line != buffer->cursorRow)
    {
        required_rows = required_screen_rows(buffer->lines[current_line]->str_len, screen->width);
        virtual_cursor_row += required_rows;
        current_line++;
    }
    virtual_cursor_row += (buffer->cursorCol) / screen->width;
    screen->cursor.x = virtual_cursor_row;
    screen->cursor.y = (buffer->cursorCol % screen->width) + 1;
}

functions.main:
int main(int argc, char *argv[])
{
    initialize(argc, argv);
    while (1)
    {
        draw_screen();
        render_screen();
        process_keypress();
    }
}

functions.initialize:
void initialize(int argc, char *argv[])
{
    if (argc >= 2)
    {
        editor_state.file_path = argv[1];
    }
    else
    {
        editor_state.file_path = "Empty Buffer";
    }
    editor_state.file_name = __xpg_basename(editor_state.file_path);
    load_file_and_initialize_buffer();
    enableRawMode();
    set_window_size();
    editor_state.screen.len = editor_state.screen.height * editor_state.screen.width * sizeof(char) * 2;
    editor_state.screen.buffer = malloc(editor_state.screen.len);
    editor_state.screen.buf_pos = 0;
    editor_state.screen.render_start_line = 0;
    editor_state.flushed = 1;
}

functions.load_file_and_initialize_buffer:
int load_file_and_initialize_buffer()
{
    FILE *fp = fopen(editor_state.file_path, "r");
    editor_state.current_buffer = CreateTextBufferFromFile(fp);
    if (editor_state.current_buffer == ((void *)0))
    {
        return 128;
    }
    if (fp == ((void *)0))
    {
        return -1;
    }
    fclose(fp);
    return 0;
}

functions.panic:
void panic(const char *message)
{
    write(1, "\x1b[2J", 4);
    write(1, "\x1b[H", 3);
    write(1, "\x1b[?25h", 6);
    perror(message);
    exit(1);
}

functions.set_window_size:
void set_window_size()
{
    struct winsize ws;
    if (ioctl(1, 0x5413, &ws) == -1 || ws.ws_col == 0)
    {
        if (write(1, "\x1b[999C\x1b[999B", 12) != 12)
        {
            panic("Failed to get window size");
        }
        char buf[32];
        for (int i = 0; i < sizeof(buf); i++)
        {
            if (read(0, &buf[i], 1) != 1)
            {
                panic("Failed to get window size");
            }
            if (buf[i] == 'R')
            {
                buf[i + 1] = '\0';
                break;
            }
        }
        if (sscanf(buf, "%d;%d", &editor_state.screen.height, &editor_state.screen.width) != 2)
        {
            panic("Failed to get windows size");
        }
    }
    else
    {
        editor_state.screen.height = ws.ws_row;
        editor_state.screen.width = ws.ws_col;
    }
}

functions.enableRawMode:
void enableRawMode()
{
    if (tcgetattr(0, &editor_state.orig_termios) == -1)
    {
        panic("tcgetattr");
    }
    atexit(disableRawMode);
    struct termios raw = editor_state.orig_termios;
    raw.c_lflag &= ~(0000010 | 0000002 | 0000001 | 0100000);
    raw.c_iflag &= ~(0000400 | 0002000 | 0000002 | 0000020);
    raw.c_oflag &= ~(0000001);
    raw.c_cflag |= (0000060);
    raw.c_cc[6] = 0;
    raw.c_cc[5] = 1;
    if (tcsetattr(0, 2, &raw) == -1)
    {
        panic("tcsetattr");
    }
}

functions.screen_append:
void screen_append(const char *str, int size)
{
    if (editor_state.screen.buffer != ((void *)0) && (editor_state.screen.len - editor_state.screen.buf_pos) > size)
    {
        memcpy(editor_state.screen.buffer + editor_state.screen.buf_pos, str, size);
        editor_state.screen.buf_pos += size;
    }
}

functions.draw_screen:
void draw_screen()
{
    editor_state.screen.buf_pos = 0;
    screen_append("\x1b[?25l", 6);
    screen_append("\x1b[2J", 4);
    screen_append("\x1b[H", 3);
    move_cursor_in_view(editor_state.current_buffer, &editor_state.screen);
    draw_editor_window(editor_state.current_buffer, &editor_state.screen);
    draw_status_line(editor_state.screen.width);
    set_virtual_cursor_position(editor_state.current_buffer, &editor_state.screen);
    int row = editor_state.screen.cursor.x;
    int col = editor_state.screen.cursor.y;
    char buf[32];
    sprintf(buf, "\x1b[%d;%dH", row, col);
    screen_append(buf, strlen(buf));
    screen_append("\x1b[?25h", 6);
    screen_append("\0", 1);
}

functions.draw_status_line:
void draw_status_line(int line_size)
{
    const char commands[] = "Ctrl+Q-quit Ctrl+S-Save";
    unsigned int commands_len = sizeof commands - 1;
    const char modified[] = "changed";
    int modified_len = sizeof modified - 1;
    int file_cursor_space = line_size - (commands_len + modified_len);
    int cur_col_digits = snprintf(((void *)0), 0, "%d", editor_state.current_buffer->cursorCol);
    int cur_row_digits = snprintf(((void *)0), 0, "%d", editor_state.current_buffer->cursorRow);
    int f_name_space = file_cursor_space - (cur_col_digits + cur_row_digits + 5);
    int file_name_size = strlen(editor_state.file_name);
    int cursor_info_buffer_size = file_cursor_space - f_name_space;
    char cursor_info_buffer[cursor_info_buffer_size];
    screen_append("\x1b[7m", 4);
    if (file_name_size > f_name_space)
    {
        screen_append(editor_state.file_name, f_name_space - 4);
        screen_append("... ", 4);
    }
    else
    {
        screen_append(editor_state.file_name, file_name_size);
    }
    sprintf(cursor_info_buffer, " | %d,%d ", editor_state.current_buffer->cursorRow,
            editor_state.current_buffer->cursorCol);
    screen_append(cursor_info_buffer, strlen(cursor_info_buffer));
    if (!editor_state.flushed)
    {
        screen_append(modified, modified_len);
    }
    else
    {
        memset(editor_state.screen.buffer + editor_state.screen.buf_pos, ' ', modified_len);
        editor_state.screen.buf_pos += modified_len;
    }
    memset(editor_state.screen.buffer + editor_state.screen.buf_pos, ' ', f_name_space - file_name_size);
    editor_state.screen.buf_pos += f_name_space - file_name_size;
    screen_append(commands, commands_len);
    screen_append("\x1b[0m", 4);
}

functions.flush_buffer_to_file:
int flush_buffer_to_file()
{
    FILE *fp = fopen(editor_state.file_path, "w");
    char *line = ((void *)0);
    if (fp == ((void *)0))
    {
        return -1;
    }
    for (int i = 0; i <= editor_state.current_buffer->last_line_loc; i++)
    {
        line = TextBufferGetLine(editor_state.current_buffer, i);
        if (line == ((void *)0))
        {
            fclose(fp);
            return -2;
        }
        if (fputs(line, fp) < strlen(line))
        {
            fclose(fp);
            return -2;
        }
    }
    fclose(fp);
    return 0;
}

functions.read_char:
int read_char()
{
    char c;
    ssize_t err;
    while ((err = read(0, &c, 1)) != 1)
    {
        if (err == 11)
        {
            panic("read_char: read() returned EAGAIN");
        }
    }
    if (c == '\x1b')
    {
        char seq[3];
        if (read(0, &seq[0], 1) != 1)
            return '\x1b';
        if (read(0, &seq[1], 1) != 1)
            return '\x1b';
        if (seq[0] == '[')
        {
            if (seq[1] >= '0' && seq[1] <= '9')
            {
                if (read(0, &seq[2], 1) != 1)
                    return '\x1b';
                if (seq[2] == '~')
                {
                    switch (seq[2])
                    {
                    case '1':
                        return HOME_KEY;
                    case '3':
                        return DEL_KEY;
                    case '4':
                        return END_KEY;
                    case '5':
                        return PAGE_UP;
                    case '6':
                        return PAGE_DOWN;
                    case '7':
                        return HOME_KEY;
                    case '8':
                        return END_KEY;
                    }
                }
            }
            else
            {
                switch (seq[1])
                {
                case 'A':
                    return ARROW_UP;
                case 'B':
                    return ARROW_DOWN;
                case 'C':
                    return ARROW_RIGHT;
                case 'D':
                    return ARROW_LEFT;
                case 'H':
                    return HOME_KEY;
                case 'F':
                    return END_KEY;
                }
            }
        }
        else if (seq[0] == 'O')
        {
            switch (seq[1])
            {
            case 'H':
                return HOME_KEY;
            case 'F':
                return END_KEY;
            }
        }
        return '\x1b';
    }
    else
    {
        return c;
    }
}

functions.process_keypress:
void process_keypress()
{
    int c = read_char();
    int err;
    switch (c)
    {
    case '\r':
        TextBufferNewLine(editor_state.current_buffer);
        break;
    case ARROW_UP:
        up_arrow();
        break;
    case ARROW_DOWN:
        down_arrow();
        break;
    case ARROW_LEFT:
        left_arrow();
        break;
    case ARROW_RIGHT:
        right_arrow();
        break;
    case PAGE_UP:
    case PAGE_DOWN:
    case HOME_KEY:
    case END_KEY:
    case DEL_KEY:
        break;
    case (('l') & 0x1f):
    case '\x1b':
        break;
    case (('s') & 0x1f):
        err = flush_buffer_to_file();
        editor_state.flushed = 1;
        break;
    case (('q') & 0x1f):
        cleanup();
        exit(0);
        break;
    case BACKSPACE:
    case (('h') & 0x1f):
        TextBufferBackspace(editor_state.current_buffer);
        editor_state.flushed = 0;
        break;
    default:
        TextBufferInsert(editor_state.current_buffer, c);
        editor_state.flushed = 0;
        break;
    }
}

functions.up_arrow:
void up_arrow()
{
    int col = editor_state.current_buffer->cursorCol;
    int row = editor_state.current_buffer->cursorRow;
    if (row > 0)
    {
        row--;
        TextBufferMoveCursor(editor_state.current_buffer, row, col);
    }
}

functions.down_arrow:
void down_arrow()
{
    int col = editor_state.current_buffer->cursorCol;
    int row = editor_state.current_buffer->cursorRow;
    if (row < editor_state.current_buffer->last_line_loc)
    {
        row++;
        TextBufferMoveCursor(editor_state.current_buffer, row, col);
    }
}

functions.left_arrow:
void left_arrow()
{
    int row = editor_state.current_buffer->cursorRow;
    int col = editor_state.current_buffer->cursorCol - 1;
    TextBufferMoveCursor(editor_state.current_buffer, row, col);
}

functions.right_arrow:
void right_arrow()
{
    int row = editor_state.current_buffer->cursorRow;
    int col = editor_state.current_buffer->cursorCol + 1;
    TextBufferMoveCursor(editor_state.current_buffer, row, col);
}

