char *TextBufferGetLine(TextBuffer *instance, int row)
{
    if (row > instance->last_line_loc)
    {
        return ((void *)0);
    }
    if (row < 0)
    {
        return ((void *)0);
    }
    return GapBufferGetString(instance->lines[row]);
